parameters.text:
=An aggregated telemetry event arrived for a live run. Decide if and what spoken cue to give the runner.

Event type: {{ $json.body.event_type }}
Window (seconds): {{ $json.body.window_seconds }}
Summary: {{ JSON.stringify($json.body.summary) }}
Run context: {{ JSON.stringify($json.body.run_context) }}

parameters.responseBody:
={
  "event_id": "{{ $('Aggregated Event In').item.json.body.event_id }}",
  "session_id": "{{ $('Aggregated Event In').item.json.body.session_id }}",
  "cue": {{ JSON.stringify($json.output.cue) }},
  "priority": {{ JSON.stringify($json.output.priority) }},
  "ttl_seconds": {{ $json.output.ttl_seconds }},
  "should_speak": {{ $json.output.should_speak }}
}
